    // === S18 — Per-tax-line proportional reversal ===
    // Reads all kind='tax_line' children for this parent split, then:
    //   1. Calls commission_split_tax_line_reverse per child (DB mirror).
    //   2. Calls tax_remittance_release per jurisdiction (ledger re-credit).
    // RPC failures log error but DO NOT throw — Stripe refund succeeded; DB mirror
    // is recoverable via reconciliation Leg 4 (Track D).

    const refundRatio = args.refundCents / charge.amount_cents;

    // §S13.3 — types.ts regen pending: commission_splits not yet in generated types.
    const fromTaxLines = supabase.from.bind(supabase) as unknown as (table: string) => {
      select: (cols: string) => {
        eq: (col: string, val: string) => {
          eq: (col2: string, val2: string) => Promise<{
            data: Array<{
              id: string;
              tax_line_id: string | null;
              jurisdiction: string | null;
              tax_amount_cents: number;
            }> | null;
            error: unknown;
          }>;
        };
      };
    };

    const { data: taxLinesData, error: taxLinesErr } = await fromTaxLines('commission_splits')
      .select('id, tax_line_id, jurisdiction, tax_amount_cents')
      .eq('parent_split_id', parentSplit.id)
      .eq('kind', 'tax_line');

    if (taxLinesErr) {
      logger.error(
        {
          refund_id: refund.id,
          parent_split_id: parentSplit.id,
          err: taxLinesErr,
        },
        'S18: failed to load tax_line children — tax reversal skipped (recoverable via reconciliation Leg 4)',
      );
    } else if (taxLinesData && taxLinesData.length > 0) {
      // Look up studio's primary location once — needed for tax_remittance_release.
      // §S13.3 — types.ts regen pending: locations not yet in generated types.
      const fromLocations = supabase.from.bind(supabase) as unknown as (table: string) => {
        select: (cols: string) => {
          eq: (col: string, val: string) => {
            limit: (n: number) => {
              maybeSingle: () => Promise<{ data: { id: string } | null; error: unknown }>;
            };
          };
        };
      };

      const { data: locationData } = await fromLocations('locations')
        .select('id')
        .eq('studio_id', args.studioId)
        .limit(1)
        .maybeSingle();

      const eventDate = new Date();
      const quarter = Math.floor(eventDate.getMonth() / 3) + 1;
      const period = `${eventDate.getFullYear()}-Q${quarter}`;

      for (const taxLine of taxLinesData) {
        const releaseTaxCents = cents(Math.round(taxLine.tax_amount_cents * refundRatio));
        if (releaseTaxCents <= 0) continue;

        // Step 1 — reverse the tax_line commission_splits row.
        const reverseIdemKey = idempotencyKeyFor('commission.tax_line.reverse', {
          parent_tax_line_split_id: taxLine.id,
          refund_id: refund.id,
        });

        const { error: taxReverseErr } = await supabase.rpc(
          RPC.COMMISSION_SPLIT_TAX_LINE_REVERSE,
          {
            p_parent_tax_line_split_id: taxLine.id,
            p_release_tax_cents: releaseTaxCents,
            p_refund_id: refund.id,
            p_idempotency_key: reverseIdemKey,
          },
        );

        if (taxReverseErr) {
          logger.error(
            {
              refund_id: refund.id,
              tax_line_id: taxLine.id,
              release_tax_cents: releaseTaxCents,
              err: taxReverseErr,
            },
            'S18: commission_split_tax_line_reverse failed — recoverable via reconciliation Leg 4',
          );
        }

        // Step 2 — re-credit tax_remittance_ledger (skip if no location or no jurisdiction).
        if (locationData && taxLine.jurisdiction) {
          const releaseLedgerIdemKey = idempotencyKeyFor('tax_remittance.release', {
            refund_id: refund.id,
            jurisdiction: taxLine.jurisdiction,
          });

          const { error: ledgerErr } = await supabase.rpc(
            RPC.TAX_REMITTANCE_RELEASE,
            {
              p_studio_id: args.studioId,
              p_location_id: locationData.id,
              p_jurisdiction: taxLine.jurisdiction,
              p_period: period,
              p_release_amount_cents: releaseTaxCents,
              p_idempotency_key: releaseLedgerIdemKey,
              p_refund_id: refund.id,
            },
          );

          if (ledgerErr) {
            logger.error(
              {
                refund_id: refund.id,
                jurisdiction: taxLine.jurisdiction,
                period,
                release_tax_cents: releaseTaxCents,
                err: ledgerErr,
              },
              'S18: tax_remittance_release failed — recoverable via reconciliation Leg 4',
            );
          }
        }
      }
    }
